package com.university.scheduler.ui;
import com.university.scheduler.dao.UiRepository;import com.university.scheduler.model.*;import javafx.collections.*;import javafx.geometry.*;import javafx.scene.Parent;import javafx.scene.control.*;import javafx.scene.layout.*;
public class CourseView{
 private final ObservableList<Course> rows=FXCollections.observableArrayList();private final TableView<Course> table=new TableView<>();
 public Parent getView(){VBox root=UiSupport.page("Courses Management","Manage courses using the composite course-code and period-type key.");TextField search=UiSupport.field("Search course code or name");Button add=new Button("+ Add Course"),refresh=new Button("Refresh");add.getStyleClass().add("primary-button");HBox bar=new HBox(10,search,refresh,add);HBox.setHgrow(search,Priority.ALWAYS);table.getColumns().addAll(UiSupport.col("Course Code",Course::getCourseCode),UiSupport.col("Course Name",c->safe(c.getCourseName())),UiSupport.col("Credits",c->c.getCredits()==null?"—":c.getCredits().toString()),UiSupport.col("Period Type",c->c.getPeriodType().name()));UiSupport.style(table);table.setItems(rows);
 TableColumn<Course,Void> act=new TableColumn<>("Actions");act.setCellFactory(c->new TableCell<>(){Button edit=new Button("Edit"),del=new Button("Delete");HBox box=new HBox(6,edit,del);{edit.setOnAction(e->dialog(getTableView().getItems().get(getIndex())));del.setOnAction(e->{Course x=getTableView().getItems().get(getIndex());if(UiSupport.confirm("Delete "+x.getCourseCode()+" / "+x.getPeriodType()+"?"))try{UiRepository.deleteCourse(x.getCourseCode(),x.getPeriodType());load();}catch(Exception ex){UiSupport.error("Could not delete course",ex);}});}protected void updateItem(Void v,boolean empty){super.updateItem(v,empty);setGraphic(empty?null:box);}});table.getColumns().add(act);search.textProperty().addListener((o,a,b)->table.setItems(rows.filtered(x->(x.getCourseCode()+safe(x.getCourseName())).toLowerCase().contains(b.toLowerCase()))));add.setOnAction(e->dialog(null));refresh.setOnAction(e->load());root.getChildren().addAll(bar,table);VBox.setVgrow(table,Priority.ALWAYS);load();return root;}
 private static String safe(String s){return s==null?"":s;}private void load(){try{rows.setAll(UiRepository.courses());table.setItems(rows);}catch(Exception e){UiSupport.error("Database connection failed while loading courses",e);}}
 private void dialog(Course old){Dialog<ButtonType>d=new Dialog<>();d.setTitle(old==null?"Add Course":"Edit Course");ButtonType save=new ButtonType("Save",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(save,ButtonType.CANCEL);TextField code=UiSupport.field("Course code (base code)"),name=UiSupport.field("Course name"),credits=UiSupport.field("Credits (optional)");ComboBox<PeriodType> type=new ComboBox<>(FXCollections.observableArrayList(PeriodType.values()));type.setValue(PeriodType.LECTURE);if(old!=null){code.setText(old.getCourseCode());code.setDisable(true);name.setText(safe(old.getCourseName()));credits.setText(old.getCredits()==null?"":old.getCredits().toString());type.setValue(old.getPeriodType());type.setDisable(true);}GridPane g=new GridPane();g.setHgap(10);g.setVgap(10);g.addRow(0,new Label("Course code"),code);g.addRow(1,new Label("Name"),name);g.addRow(2,new Label("Credits"),credits);g.addRow(3,new Label("Period type"),type);d.getDialogPane().setContent(g);d.showAndWait().ifPresent(b->{if(b==save)try{Integer n=credits.getText().isBlank()?null:Integer.valueOf(credits.getText().trim());if(code.getText().isBlank()||(n!=null&&n<0))throw new IllegalArgumentException("Enter a course code and valid credits.");UiRepository.saveCourse(new Course(code.getText().trim(),name.getText().trim(),n,type.getValue()),old!=null);load();}catch(Exception ex){UiSupport.error("Could not save course",ex);}});}
}
